/** Role-based colors. Names follow shadcn/ui conventions so the web component library maps 1:1. */
export interface SemanticColors {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  success: string;
  warning: string;
  info: string;
  border: string;
  input: string;
  ring: string;
  /** Positive behaviour points (ClassDojo-style green bubble). */
  pointsPositive: string;
  /** "Needs work" points (D2): warm, not alarming. */
  pointsNeedsWork: string;
}

