/** Corner radii in px. Generous rounding is part of the friendly look. */
export const radii = { sm: 8, md: 12, lg: 16, xl: 20, '2xl': 28, full: 9999 } as const;

/** 4-pt spacing scale in px (mobile; web uses Tailwind's matching 0.25rem scale). */
export const spacing = { 0: 0, 1: 4, 2: 8, 3: 12, 4: 16, 5: 20, 6: 24, 8: 32, 10: 40, 12: 48, 16: 64 } as const;

/** Minimum touch target (px) for every tappable control. */
export const minTouchTarget = 44;

export const typography = {
  /**
   * Rounded Latin face + Noto Sans Ethiopic so Amharic/Tigrinya render with a matching
   * weight. Font files are loaded by each app (next/font on web, expo-font on mobile).
   */
  fontFamily: {
    sans: ['Nunito', 'Noto Sans Ethiopic', 'system-ui', 'sans-serif'],
    ethiopic: ['Noto Sans Ethiopic', 'Nunito', 'system-ui', 'sans-serif'],
    mono: ['ui-monospace', 'SFMono-Regular', 'Menlo', 'monospace'],
  },
  /** Size in px and unitless line height. Ethiopic glyphs need taller lines than Latin. */
  fontSize: {
    xs: { size: 12, lineHeight: 1.6 },
    sm: { size: 14, lineHeight: 1.6 },
    base: { size: 16, lineHeight: 1.6 },
    lg: { size: 18, lineHeight: 1.55 },
    xl: { size: 20, lineHeight: 1.5 },
    '2xl': { size: 24, lineHeight: 1.4 },
    '3xl': { size: 30, lineHeight: 1.3 },
    '4xl': { size: 36, lineHeight: 1.25 },
  },
  fontWeight: { regular: 400, medium: 500, semibold: 600, bold: 700, extrabold: 800 },
} as const;

export const shadows = {
  card: '0 1px 2px rgba(15, 23, 42, 0.06), 0 4px 12px rgba(15, 23, 42, 0.06)',
  raised: '0 4px 8px rgba(15, 23, 42, 0.08), 0 12px 28px rgba(15, 23, 42, 0.10)',
} as const;

export const tokens = { palette, colors, radii, spacing, minTouchTarget, typography, shadows } as const;
